effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////



   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 ryu;
        // if (adaptive) { 
        ryu = acScreenNorm; 

    	vec4 fragColor;

              	vec2 uv = ryu;

        	vec3 orig = texture2DCv(inputImg.texture, uv).xyz;	// ...this is the video

        	vec3 col = orig * orig * progressa; 				// ...some contrast
        	float bri = (col.x+col.y+col.z)/2.0;		// ...it's ok it's black and white!

        	float v = smoothstep(.0, progressc, bri);			// ...tint the dark values into cyan/teal.
        	col = mix(vec3(progressd, progresse, progressf) * bri, col, v);

        	v = smoothstep(0.2, 1.1, bri);				// ...tint the light values into orange.
        	col = mix(col, min(vec3(1.0, 0.5, 0.0) * bri, 1.0), v);

        	float x = 0.0; //
        	col = mix(orig, col, step(x, uv.x));		// ...mouse X to slide filter
        	fragColor = vec4(min(col, 1.0),1.0);

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
